select energy_manager.load_cards($cards$[
{"id":"p2-b06-039","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What does high moisture content in biomass cause in the boiler?","back":"Frequent jamming of fuel in feeders, causing steam pressure and temperature fluctuations, and plugging and choking of closely spaced heating surfaces.","explain":"Tight super-heater coil spacing, often chosen for compact design, makes the plugging worse.","flash":false,"source":"BEE Book 2 Ch 06 p213","order":2332},
{"id":"p2-b06-040","paper":2,"topic":"FBC Boilers","kind":"fact","front":"In an FBC boiler, if the bed temperature exceeds 950 °C, what is the likely result: sand heating, ash fusion, melting of limestone or ash carry-over?","back":"Ash fusion (clinker formation).","explain":"The chapter notes that clinker forms in the bed above 950 °C, and FBC keeps the bed below ash fusion temperature.","flash":false,"source":"BEE Book 2 Ch 06 p214","order":2333},
{"id":"p2-b06-041","paper":2,"topic":"FBC Boilers","kind":"fact","front":"In a CFBC, which device captures and recycles the bed material: bag filter, settling chamber, cyclone or scrubber?","back":"Cyclone.","explain":"CFBC needs huge mechanical cyclones to capture and recycle the large amount of bed material. This is also why CFBC boilers are tall.","flash":false,"source":"BEE Book 2 Ch 06 p214","order":2334},
{"id":"p2-b06-042","paper":2,"topic":"FBC Boilers","kind":"fact","front":"What is the typical overall efficiency of an FBC boiler: 90%, 80%, 60% or 50%?","back":"About 80%, the closest option. The chapter gives 84 percent plus or minus 2 percent.","explain":"Choose 80 percent from the options given, but note the book states 84 percent plus or minus 2 percent. Read the exact figure before answering.","flash":true,"source":"BEE Book 2 Ch 06 p214","order":2335},
{"id":"p2-b06-043","paper":2,"topic":"FBC Boilers","kind":"fact","front":"Explain the concept of an FBC boiler with a sketch. What are its major benefits?","back":"Air is blown up through a bed of fine solid particles on a distributor. At sufficient velocity the bed fluidizes and burns crushed fuel at about 840 to 950 °C. Major benefits: high efficiency, compact size, fuel flexibility, low SO₂ and NOₓ, low corrosion, no clinker, quick load response and low maintenance.","explain":"A sketch should show the air distributor, the bed with in-bed heat transfer tubes, the dust collection path and the boiler. Fluidization gives the turbulence and heat transfer behind these benefits.","flash":false,"source":"BEE Book 2 Ch 06 p215","order":2336},
{"id":"p2-b07-001","paper":2,"topic":"Need for Cogeneration","kind":"fact","front":"What is the typical efficiency of a conventional thermal power plant, and what happens to the rest of the energy?","back":"About 35%. The other ~65% is lost, mainly as heat rejected to cooling water or air because of the limits of thermodynamic cycles.","explain":"Further losses of about 10-15% occur in transmission and distribution on the grid. Cogeneration tackles the problem by using heat that would otherwise be rejected.","flash":true,"source":"BEE Book 2 Ch 07 p219","order":2337},
{"id":"p2-b07-002","paper":2,"topic":"Need for Cogeneration","kind":"problem","front":"In the coal-fired power station energy balance (100 GJ input), what is the thermal efficiency and how much energy is lost in total?","back":"Thermal efficiency = 36.2%. Total loss = 63.8 GJ.","explain":"The book's figure labels the electricity output 36.3 GJ in one place, but its efficiency line uses 36.2 GJ. The itemised losses add up to the balance, which confirms the 63.8 GJ loss.","flash":false,"source":"BEE Book 2 Ch 07 p219","steps":[{"prompt":"Identify the input and output energy.","answer":"Input = 100 GJ (coal energy). Output = 36.2 GJ of electricity to the system.","explain":"Efficiency is always useful output divided by input on the same basis."},{"prompt":"Calculate the thermal efficiency.","answer":"36.2 / 100 x 100 = 36.2%.","explain":"This matches the efficiency line printed under the balance diagram."},{"prompt":"Calculate the total energy lost.","answer":"100 - 36.2 = 63.8 GJ.","explain":"Every GJ that is not delivered as electricity appears as a loss in the balance."},{"prompt":"Cross-check the itemised losses.","answer":"Stack 10.2 + hot surfaces 1.0 + boiler leaks 0.8 + cooling tower/condenser 48.3 + unburnt carbon in ash and dust 0.7 + auxiliaries 2.8 = 63.8 GJ.","explain":"The items sum to the total loss, so the balance closes. The condenser/cooling-tower loss is by far the largest slice."}],"order":2338},
{"id":"p2-b07-003","paper":2,"topic":"Cogeneration Basics","kind":"fact","front":"What overall energy-use efficiency can cogeneration reach?","back":"Up to 85%, and above in some cases.","explain":"A conventional electricity-only plant manages about 35%. The gain comes from using the heat that a power plant would otherwise reject.","flash":true,"source":"BEE Book 2 Ch 07 p220","order":2339},
{"id":"p2-b07-004","paper":2,"topic":"Cogeneration Basics","kind":"fact","front":"What two useful forms of energy does cogeneration produce from one primary energy source?","back":"Mechanical energy and thermal energy.","explain":"Mechanical energy can drive an alternator or equipment such as a motor, compressor, pump or fan. Thermal energy can serve direct process use or produce steam, hot water, hot air or chilled water.","flash":false,"source":"BEE Book 2 Ch 07 p220","order":2340},
{"id":"p2-b07-005","paper":2,"topic":"Cogeneration Basics","kind":"problem","front":"An industry needs 24 units of electricity and 34 units of heat. Compare the fuel needed by separate production (power station 40%, boiler 85%) with cogeneration (85% overall). How much fuel is saved?","back":"Separate production needs 100 units; cogeneration needs 68 units. Saving = 32 units (32%).","explain":"Cogeneration cuts the losses from 42 units to 10 units. Most of the saving comes from not losing the heat that a separate power station would reject.","flash":false,"source":"BEE Book 2 Ch 07 p220","steps":[{"prompt":"Fuel for the electricity in a separate power station.","answer":"24 / 0.40 = 60 units.","explain":"A 40% efficient station needs 60 units of fuel for 24 units of electricity."},{"prompt":"Fuel for the heat in a separate boiler.","answer":"34 / 0.85 = 40 units.","explain":"An 85% efficient boiler needs 40 units of fuel for 34 units of heat."},{"prompt":"Total fuel with separate production.","answer":"60 + 40 = 100 units.","explain":"This is the baseline for the comparison."},{"prompt":"Fuel with cogeneration.","answer":"(24 + 34) / 0.85 = 68 units.","explain":"One plant at 85% overall efficiency serves both loads."},{"prompt":"Fuel saved.","answer":"100 - 68 = 32 units, which is 32% of the separate-production fuel.","explain":"Losses fall from 42 units (100 - 58) to 10 units (68 - 58)."}],"order":2341},
{"id":"p2-b07-006","paper":2,"topic":"Cogeneration Basics","kind":"fact","front":"What are the macro-level and micro-level benefits of cogeneration?","back":"Macro: it shares part of the national utility's financial burden with the private sector and conserves indigenous energy sources. Micro: it can cut a user's overall energy bill, especially where power and heat are needed together and tariffs are rational.","explain":"At the national level, cogeneration spreads the investment burden. At site level, the saving depends on having a simultaneous need for both power and heat.","flash":false,"source":"BEE Book 2 Ch 07 p220","order":2342},
{"id":"p2-b07-007","paper":2,"topic":"Cogeneration Basics","kind":"fact","front":"Why does on-site cogeneration reduce the burden on the utility network?","back":"Electricity is generated on-site, so the grid carries less load and the transmission line losses are eliminated.","explain":"Cogeneration also saves fossil fuel and reduces greenhouse gas emissions, particularly CO₂.","flash":false,"source":"BEE Book 2 Ch 07 p220","order":2343},
{"id":"p2-b07-008","paper":2,"topic":"Cogeneration Technologies","kind":"fact","front":"Name the three cogeneration technologies that have been widely commercialised.","back":"(1) Extraction or back-pressure steam turbines. (2) Gas turbine with heat recovery boiler, with or without a bottoming steam turbine. (3) Reciprocating engines with heat recovery boiler.","explain":"These three are the mainstream options. The chapter then describes each one in turn, with its heat-to-power characteristics.","flash":true,"source":"BEE Book 2 Ch 07 p221","order":2344},
{"id":"p2-b07-009","paper":2,"topic":"Steam Turbine Cogeneration","kind":"fact","front":"What is a specific advantage of steam turbines over other prime movers in cogeneration?","back":"They can burn a wide range of fuels, including coal, natural gas, fuel oil and biomass.","explain":"Some power generation efficiency may be given up to optimise heat supply. Steam turbines are mostly used where electricity demand is above 1 MW, up to a few hundred MW.","flash":false,"source":"BEE Book 2 Ch 07 p221","order":2345},
{"id":"p2-b07-010","paper":2,"topic":"Steam Turbine Cogeneration","kind":"fact","front":"Why are back-pressure cogeneration plants free of the need for large cooling towers?","back":"Their exhaust steam is used by the process, so there is no large condensing system to reject leftover heat.","explain":"Condensing turbines need a condenser and cooling tower to reject the heat that is not used. Back-pressure plants avoid that equipment.","flash":false,"source":"BEE Book 2 Ch 07 p221","order":2346},
{"id":"p2-b07-011","paper":2,"topic":"Gas Turbine Cogeneration","kind":"fact","front":"What size range do gas turbines cover in cogeneration, and which fuel is most common?","back":"From a fraction of a MW to about 100 MW. Natural gas is the most common fuel; light fuel oil or diesel can also be used.","explain":"Gas turbine cogeneration has grown fast because of natural gas availability, shorter project gestation and modular delivery.","flash":false,"source":"BEE Book 2 Ch 07 p222","order":2347},
{"id":"p2-b07-012","paper":2,"topic":"Gas Turbine Cogeneration","kind":"fact","front":"What is the main trade-off of gas turbine cogeneration between heat and power?","back":"Low heat-to-power conversion efficiency, but more heat can be recovered at higher temperatures.","explain":"The high-temperature exhaust suits a wide range of heating and cooling uses. Gas turbines also have a short start-up time and can run intermittently.","flash":false,"source":"BEE Book 2 Ch 07 p222","order":2348},
{"id":"p2-b07-013","paper":2,"topic":"Gas Turbine Cogeneration","kind":"fact","front":"How can a gas turbine cogeneration unit boost its heat output when the site needs more heat?","back":"Supplementary natural gas firing: extra fuel is mixed into the oxygen-rich exhaust gas and burned.","explain":"The exhaust still holds oxygen, so the extra firing raises thermal output efficiently. Many large units use this to change their heat-to-power ratio.","flash":false,"source":"BEE Book 2 Ch 07 p222","order":2349},
{"id":"p2-b07-014","paper":2,"topic":"Reciprocating Engines","kind":"fact","front":"Why are reciprocating engines popular with smaller energy-consuming facilities?","back":"They have high power generation efficiency, their heat recovery is efficient at small sizes, and they suit sites that need more electricity than heat, where low-quality heat (low-pressure steam or hot water) is acceptable.","explain":"Reciprocating engines are ideal for intermittent operation. Their performance is not as sensitive to ambient temperature as that of gas turbines.","flash":false,"source":"BEE Book 2 Ch 07 p223","order":2350},
{"id":"p2-b07-015","paper":2,"topic":"Reciprocating Engines","kind":"fact","front":"True or false: reciprocating engine performance is more sensitive to ambient temperature than gas turbine performance.","back":"False. Engine performance is not as sensitive to ambient temperature changes as gas turbine performance.","explain":"The drawback of engines is cost, not temperature sensitivity: a low initial investment, but high operating and maintenance costs from wear and tear.","flash":false,"source":"BEE Book 2 Ch 07 p223","order":2351},
{"id":"p2-b07-016","paper":2,"topic":"Topping and Bottoming Cycles","kind":"fact","front":"Name the four types of topping cycle cogeneration.","back":"(1) Combined-cycle topping: gas turbine, then heat recovery boiler, then steam turbine. (2) Steam-turbine topping: high-pressure boiler steam through a turbine, with low-pressure exhaust for process. (3) Diesel or gas engine with heat recovery from exhaust and jacket water. (4) Gas-turbine topping: gas turbine drives a generator and its exhaust feeds a heat recovery boiler.","explain":"In a topping cycle the fuel makes power first, and the leftover heat is the by-product used for process heat. Topping cycles are the most popular form of cogeneration.","flash":false,"source":"BEE Book 2 Ch 07 p224","order":2352},
{"id":"p2-b07-017","paper":2,"topic":"Topping and Bottoming Cycles","kind":"fact","front":"Which industries mainly use bottoming-cycle cogeneration, and why?","back":"Cement, steel, ceramic, gas and petrochemical industries, where high-temperature furnace or kiln heat is rejected at significantly high temperatures.","explain":"The rejected heat drives a recovery boiler and turbine-generator to make power. Bottoming-cycle plants are much less common than topping-cycle plants.","flash":true,"source":"BEE Book 2 Ch 07 p225","order":2353},
{"id":"p2-b07-018","paper":2,"topic":"Load Matching","kind":"fact","front":"In base electrical load matching, how is the plant sized and how is the rest of the power supplied?","back":"It is sized to the site's minimum electricity demand, taken from the historical demand curve. The rest of the power is bought from the grid.","explain":"Thermal demand can be met by the cogeneration system alone or with additional boilers. Surplus heat can be exported to neighbouring customers if the situation permits.","flash":false,"source":"BEE Book 2 Ch 07 p226","order":2354},
{"id":"p2-b07-019","paper":2,"topic":"Load Matching","kind":"fact","front":"In base thermal load matching, how is the plant sized and what covers extra demand?","back":"It is sized to the minimum thermal requirement and runs at full load at all times. Standby boilers or burners supply the extra heat, and extra power is bought from the grid.","explain":"If local law permits, excess electricity can be sold to the power utility.","flash":false,"source":"BEE Book 2 Ch 07 p226","order":2355},
{"id":"p2-b07-020","paper":2,"topic":"Load Matching","kind":"fact","front":"Which operating scheme makes a facility a stand-alone system, independent of the utility grid?","back":"Electrical load matching.","explain":"The system must cover all site power needs, including reserves for scheduled and unscheduled maintenance. Auxiliary boilers meet any extra heat demand, and surplus heat is wasted unless it can be exported.","flash":false,"source":"BEE Book 2 Ch 07 p226","order":2356},
{"id":"p2-b07-021","paper":2,"topic":"Load Matching","kind":"fact","front":"In thermal load matching, what does the plant follow, and how are power deficits and surpluses handled?","back":"It follows the site's heat demand at any time. A power shortfall is bought from the grid, and excess electricity can be sold to the utility if local legislation permits.","explain":"The prime movers are operated according to the thermal demand, so electricity output is set by the heat requirement.","flash":false,"source":"BEE Book 2 Ch 07 p226","order":2357},
{"id":"p2-b07-022","paper":2,"topic":"Heat-to-Power Ratio","kind":"fact","front":"Which cogeneration system has the widest heat-to-power ratio range, and what is it?","back":"Back-pressure steam turbine, 4.0 to 14.3. For comparison: extraction-condensing steam turbine 2.0 to 10.0; gas turbine 1.3 to 2.0; combined cycle 1.0 to 1.7; reciprocating engine 1.1 to 2.5.","explain":"The steam turbine offers a large range of heat-to-power ratios, which is why it fits many different sites. Both heat and power are expressed in the same unit (kW) for the ratio.","flash":true,"source":"BEE Book 2 Ch 07 p227","order":2358},
{"id":"p2-b07-023","paper":2,"topic":"Cogeneration Attractiveness","kind":"fact","front":"Under what three conditions is cogeneration most attractive?","back":"(a) Steam and power demand are balanced, within the steam-to-power output range of a suitable plant. (b) One plant or a group of plants has enough steam and power demand for economies of scale. (c) Peaks and troughs in demand can be managed, or adequate utility backup is available for electricity.","explain":"These conditions link the heat-to-power ratio to the load-matching schemes. Electricity backup is what allows a plant to cover demand peaks.","flash":false,"source":"BEE Book 2 Ch 07 p228","order":2359},
{"id":"p2-b07-024","paper":2,"topic":"Site Selection Factors","kind":"fact","front":"Why does a sugar mill (heat at about 120 °C) suit a topping cycle, while a cement plant (heat at about 1450 °C) suits a bottoming cycle?","back":"Lower-temperature heat, such as a sugar mill's 120 °C, fits a topping cycle. Very high-temperature heat, such as a cement plant's 1450 °C, fits a bottoming cycle, which also supplies electricity.","explain":"The required quality of thermal energy (temperature and pressure) decides the type of cogeneration system.","flash":false,"source":"BEE Book 2 Ch 07 p228","order":2360},
{"id":"p2-b07-025","paper":2,"topic":"Site Selection Factors","kind":"fact","front":"Why is a rice mill a good candidate for steam turbine cogeneration?","back":"It needs mechanical power for milling and heat for paddy drying, and a steam turbine can burn rice husk, the mill's own waste product.","explain":"Cheap fuels or waste products often decide whether a cogeneration option is competitive, because they set the running cost.","flash":false,"source":"BEE Book 2 Ch 07 p229","order":2361},
{"id":"p2-b07-026","paper":2,"topic":"Site Selection Factors","kind":"fact","front":"Why should cogeneration for a pulp and paper plant be modular?","back":"The plant cannot run long without process steam, so the system should have more than one unit. If one unit shuts down, the energy supply is not seriously affected.","explain":"Modularity is a reliability feature for sites that cannot tolerate a prolonged loss of heat or power.","flash":false,"source":"BEE Book 2 Ch 07 p229","order":2362},
{"id":"p2-b07-027","paper":2,"topic":"Site Selection Factors","kind":"fact","front":"How does a grid-dependent cogeneration system differ from a grid-independent (stand-alone) one?","back":"A grid-dependent system can buy or sell electricity through the grid. A stand-alone system meets all of the site's energy demands by itself.","explain":"For the same facility, the technical configuration differs between the two designs, so the choice must be made early.","flash":false,"source":"BEE Book 2 Ch 07 p229","order":2363},
{"id":"p2-b07-028","paper":2,"topic":"Site Selection Factors","kind":"fact","front":"How can local environmental regulations limit the cogeneration choice?","back":"Stringent rules can rule out some fuels, because the cost of treating polluted exhaust gas, or of treating the fuel itself, can be too high.","explain":"Environmental rules therefore affect the technology and fuel choice, not only emissions limits.","flash":false,"source":"BEE Book 2 Ch 07 p230","order":2364},
{"id":"p2-b07-029","paper":2,"topic":"Steam Turbine Cogeneration","kind":"fact","front":"What overall thermal efficiency can a back-pressure cogeneration system reach with an efficient boiler?","back":"As much as 90%, when all the exhaust steam is used. The only other losses are gear drive, generator and steam generation.","explain":"The chapter's notes on cogeneration efficiency quote up to 85% for back-pressure systems. Both figures appear in the book, so use the number the question asks for.","flash":false,"source":"BEE Book 2 Ch 07 p231","order":2365},
{"id":"p2-b07-030","paper":2,"topic":"Steam Turbine Cogeneration","kind":"fact","front":"Compared with a back-pressure turbine, what does an extraction-condensing turbine offer, and what does it cost?","back":"A higher power-to-heat ratio and higher electricity generation efficiency. The cost is a lower overall thermal efficiency, because exhaust heat is lost in the cooling water.","explain":"Condensing systems need more auxiliary equipment, such as the condenser and cooling towers. They suit sites where electricity demand is much higher than steam demand and the load fluctuates.","flash":false,"source":"BEE Book 2 Ch 07 p232","order":2366},
{"id":"p2-b07-031","paper":2,"topic":"Gas Turbine Cogeneration","kind":"fact","front":"What temperatures apply to gas turbine gases at inlet and exhaust, and why is the exhaust useful?","back":"Gases enter at 900-1000 °C and leave at about 450-550 °C. The book gives 400-500 °C for the exit in one place. The hot exhaust makes the gas turbine well suited to high-grade heat supply.","explain":"The exhaust can meet all or part of the site's thermal (steam) demand. The OCR of the chapter shows the exit range twice with slightly different numbers.","flash":false,"source":"BEE Book 2 Ch 07 p232","order":2367},
{"id":"p2-b07-032","paper":2,"topic":"Gas Turbine Cogeneration","kind":"fact","front":"Which fuels suit gas turbines, and why must the hot gas be clean?","back":"Natural gas is most used. Gas oil, LPG and naphtha are also suitable. The hot gas must be free of particulates that erode the blades and of contaminants that cause corrosion.","explain":"A gas turbine runs at high speed and high temperature, so high-premium fuels are preferred. Distillate oils such as gas oil are also used.","flash":false,"source":"BEE Book 2 Ch 07 p232","order":2368},
{"id":"p2-b07-033","paper":2,"topic":"Turbine Efficiency","kind":"fact","front":"What is the efficiency of a stand-alone gas turbine without any heat recovery system?","back":"About 35 to 40%.","explain":"Losses come from blade efficiency, leakage through clearance spaces, friction and turbulence. Heat recovery in a steam generator is what recovers much of the rest.","flash":false,"source":"BEE Book 2 Ch 07 p233","order":2369},
{"id":"p2-b07-034","paper":2,"topic":"Turbine Efficiency","kind":"fact","front":"What share of the turbine's generated energy does the air compressor consume, and what does that do to net efficiency?","back":"About 50 to 60%. The 35-40% figures exclude the compressor, fuel pump and other auxiliaries, so the net turbine efficiency is lower than the calculated figure.","explain":"In most gas turbine plants the air compressor is an integral part of the turbine plant, so the net figure is the one that counts for usable output.","flash":true,"source":"BEE Book 2 Ch 07 p233","order":2370},
{"id":"p2-b07-035","paper":2,"topic":"Turbine Performance","kind":"fact","front":"What is turbine heat rate, and in which units is it expressed?","back":"The heat input to the turbine needed to produce 1 kWh of electricity. It is expressed in kJ/kWh (or kcal/kWh). 1 kWh = 3,600 kJ = 860 kcal.","explain":"Heat rate and efficiency are inversely related only for a pure power plant. For cogeneration, the useful process heat is not counted in the heat rate, so the inverse does not apply.","flash":false,"source":"BEE Book 2 Ch 07 p236","order":2371},
{"id":"p2-b07-036","paper":2,"topic":"Turbine Performance","kind":"fact","front":"What is a pressure survey on a steam turbine, and what conditions must it meet?","back":"Pressure is noted at tapping points along the expansion path and compared with design values to infer the turbine's internal condition. The gauges must be accurate and the readings taken while the load is steady.","explain":"A pressure survey should be carried out frequently on each running machine, because it shows deviations in performance early.","flash":false,"source":"BEE Book 2 Ch 07 p236","order":2372},
{"id":"p2-b07-037","paper":2,"topic":"Heat-to-Power Ratio","kind":"problem","front":"For Case 1 of the illustrative cogeneration plant (6 MW electrical output, normal process flow), find the heat-to-power ratio. Process extraction: 13,470 kg/h at 3,011.35 kJ/kg with return condensate at 293 kJ/kg. Deaerator bleed: 3,550 kg/h at 2,835.8 kJ/kg.","back":"Heat-to-power ratio ≈ 2.16 (thermal output ≈ 12,968 kW against 6,000 kW electrical).","explain":"The ratio compares useful thermal output with electrical output in the same unit (kW). Converting kJ/h to kW uses 1 kWh = 3,600 kJ.","flash":false,"source":"BEE Book 2 Ch 07 p238","steps":[{"prompt":"Heat carried away in the process extraction.","answer":"13,470 x (3,011.35 - 293) = 36,616,174.5 kJ/h.","explain":"The useful heat is the enthalpy drop from the extracted steam to the return condensate."},{"prompt":"Heat carried away in the deaerator bleed.","answer":"3,550 x 2,835.8 = 10,067,090 kJ/h.","explain":"The book takes the bleed's full enthalpy as useful heat in this calculation."},{"prompt":"Total thermal output in kW.","answer":"(36,616,174.5 + 10,067,090) / 3,600 = 12,967.6 kW.","explain":"Dividing kJ/h by 3,600 gives kW, because 1 kWh = 3,600 kJ."},{"prompt":"Heat-to-power ratio.","answer":"12,967.6 / 6,000 = 2.16.","explain":"The ratio is dimensionless (kW/kW). A value of 2.16 means 2.16 kW of heat for each kW of electricity."}],"order":2373},
{"id":"p2-b07-038","paper":2,"topic":"Energy Utilisation Factor","kind":"problem","front":"For the same Case 1 plant (boiler efficiency 83%, steam 34,800 kg/h at 3,418 kJ/kg, feed water at 251 kJ/kg), find the Energy Utilisation Factor (EUF).","back":"EUF ≈ 51.43%.","explain":"EUF counts both electrical and useful thermal output against fuel heat input, so it is much higher than the electrical efficiency of the plant.","flash":false,"source":"BEE Book 2 Ch 07 p238","steps":[{"prompt":"Electrical output in Mcal/h.","answer":"6,000 kW x 860 kcal/kWh = 5,160,000 kcal/h = 5,160 Mcal/h.","explain":"Each kWh is 860 kcal, the thermal equivalent of electricity."},{"prompt":"Thermal output in Mcal/h.","answer":"46,683,264.5 kJ/h / 4.187 = 11,150 Mcal/h.","explain":"The two extraction streams from the heat calculation, converted from kJ to kcal with 4.187 kJ/kcal."},{"prompt":"Fuel heat input in Mcal/h.","answer":"34,800 x (3,418 - 251) / 4.187 = 26,322 Mcal/h, then / 0.83 = 31,714 Mcal/h.","explain":"Steam heat is divided by boiler efficiency to give the fuel heat input."},{"prompt":"Energy Utilisation Factor.","answer":"(5,160 + 11,150) / 31,714 = 51.43%.","explain":"Useful output over fuel input. Counting the process heat is what lifts the factor above the power-only efficiency."}],"order":2374},
{"id":"p2-b07-039","paper":2,"topic":"Trigeneration","kind":"fact","front":"What is trigeneration?","back":"Simultaneous generation of steam (heat), power and refrigeration through integrated systems.","explain":"Food processing and cold storage benefit most. A combined-cycle trigeneration plant with a gas turbine, waste heat boiler, steam turbine and absorption chiller can meet 100% of the facility's needs, with surplus power sold to the grid.","flash":true,"source":"BEE Book 2 Ch 07 p238","order":2375},
{"id":"p2-b07-040","paper":2,"topic":"Steam Economics","kind":"problem","front":"A chemical plant reduces steam from 17.6 kg/cm²(g) to 1.8 kg/cm²(g) through a PRV for a process needing 5,189 Mcal/h. Replacing the PRV with a back-pressure turbine (8,000 h/yr, fuel 10,000 kcal/kg at Rs 25/kg, grid power at Rs 6/kWh, gearbox 98%, alternator 98%, mechanical 97%, boiler 85%): what is the annual net saving?","back":"About Rs 114.5 lakh per year. Power = 434 kW. Extra fuel cost = Rs 1,172.5/h. Grid saving = Rs 2,604/h. Net = Rs 1,431.5/h x 8,000 h.","explain":"The turbine needs more steam to deliver the same process heat, because its exit enthalpy is lower. The power it makes is therefore not free, but the grid power it displaces is worth more than the extra fuel.","flash":false,"source":"BEE Book 2 Ch 07 p240","steps":[{"prompt":"Fuel rate with the PRV (steam 9,072 kg/h).","answer":"9,072 x (668 - 94.5) / (0.85 x 10,000) = 612.1 kg/h.","explain":"Heat taken from the steam (668 minus condensate 94.5 kcal/kg), divided by boiler efficiency and fuel calorific value."},{"prompt":"Fuel rate with the back-pressure turbine (steam 9,767 kg/h).","answer":"9,767 x 573.5 / 8,500 = 659 kg/h.","explain":"The turbine needs more steam so that the process still gets the same heat duty at a lower exit enthalpy."},{"prompt":"Extra fuel cost.","answer":"(659 - 612.1) = 46.9 kg/h x Rs 25/kg = Rs 1,172.5/h.","explain":"Rs 25,000 per tonne equals Rs 25 per kg."},{"prompt":"Power generated.","answer":"9,767 x (668 - 627) x 0.98 x 0.98 x 0.97 / 860 = 434 kW.","explain":"Enthalpy drop from 668 to 627 kcal/kg, converted with 860 kcal/kWh, then reduced by gearbox, alternator and turbine mechanical efficiencies."},{"prompt":"Net hourly benefit.","answer":"434 kW x Rs 6 = Rs 2,604/h; net = 2,604 - 1,172.5 = Rs 1,431.5/h.","explain":"Grid power saved minus extra fuel cost, before annualising."},{"prompt":"Annual net saving.","answer":"1,431.5 x 8,000 = Rs 11,452,000, i.e. about Rs 114.5 lakh per year.","explain":"Operating hours convert the hourly benefit to an annual figure."}],"order":2376}
]$cards$::jsonb);
